+    private int _pageSize = 12;
+    private int _totalCount;
+    private int _totalPages;
+    private bool _loading = true;
+    private string? _error;
+
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadInitialData();
+    }
+
+    private async Task LoadInitialData()
+    {
+        try
+        {
+            _loading = true;
+            _error = null;
+
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, _pageSize);
+
+            await Task.WhenAll(categoriesTask, productsTask);
+
+            _categories = await categoriesTask;
+            var result = await productsTask;
+            ApplyResult(result);
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task LoadProducts()
+    {
+        try
+        {
+            _loading = true;
+            _error = null;
+            StateHasChanged();
+
+            var result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, _pageSize);
+            ApplyResult(result);
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private void ApplyResult(PagedResult<Product> result)
+    {
+        _products = result.Items;
+        _totalCount = result.TotalCount;
+        _currentPage = result.Page;
+        _totalPages = (int)Math.Ceiling((double)result.TotalCount / result.PageSize);
+    }
+
+    private async Task HandleFiltersApplied(ProductFilter filter)
+    {
+        _filter = filter;
+        _currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandleFiltersCleared()
+    {
+        _filter = new ProductFilter(null, null, null, false);
+        _currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandleSortChanged(string sortBy)
+    {
+        _sortBy = sortBy;
+        _currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task HandlePageChanged(int page)
+    {
+        _currentPage = page;
+        await LoadProducts();
+    }
+
+    private async Task HandleProductSelected(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Placeholder for cart functionality
+        return Task.CompletedTask;
+    }
+}
